def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the dp table with -inf
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    # Fill the dp table
    for i in range(N):
        for j in range(N):
            for k in range(max(0, i + j - N + 1), min(N, i + j + 1)):
                l = i + j - k
                if i > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j])
                if j > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[i][j])
                if k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1] + grid[k][l])
                if l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k] + grid[k][l] if k != i or l != j else 0)

    return dp[N-1][N-1][N-1] if dp[N-1][N-1][N-1] != -float('inf') else 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    if N <= 0:
        return 0

    # Initialize grid with zeros
    grid = [[0] * (N + 1) for _ in range(N + 1)]

    # Fill the grid with values from grid_values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x][y] = value

    # DP table to store the maximum sum of values collected by two paths
    dp = [[[[0] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)] for _ in range(N + 1)]

    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                l = i + j - k
                if l < 1 or l > N:
                    continue

                # Collect values for both paths
                val = grid[i][j] + (grid[k][l] if (i != k or j != l) else 0)

                # Update DP table
                dp[i][j][k][l] = val + max(
                    dp[i - 1][j][k - 1][l],
                    dp[i - 1][j][k][l - 1],
                    dp[i][j - 1][k - 1][l],
                    dp[i][j - 1][k][l - 1]
                )

    return dp[N][N][N][N]

