def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with values
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N * 2 - 1)]

    # Base case
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for step in range(1, 2 * N - 1):
        for i1 in range(max(0, step - (N - 1)), min(step + 1, N)):
            for i2 in range(max(0, step - (N - 1)), min(step + 1, N)):
                j1, j2 = step - i1, step - i2
                if j1 < 0 or j1 >= N or j2 < 0 or j2 >= N:
                    continue
                val = grid[i1][j1] + (grid[i2][j2] if i1 != i2 or j1 != j2 else 0)
                dp[step][i1][i2] = val + max(
                    dp[step - 1][i1 - 1][i2 - 1],  # both move diagonally
                    dp[step - 1][i1 - 1][i2],     # p1 moves down, p2 moves right
                    dp[step - 1][i1][i2 - 1],     # p1 moves right, p2 moves down
                    dp[step - 1][i1][i2]          # both move right
                )

    return max(dp[-1][i][j] for i in range(N) for j in range(N) if dp[-1][i][j] != -float('inf'))

