        raise ValueError("Invalid input values")

    # Function to calculate the product of a list of numbers
    def product_of_list(lst):
        product = 1
        for num in lst:
            product *= num
        return product

    # Function to recursively find the maximum product
    def find_max_product(index, remaining_multiplications):
        if remaining_multiplications == 0:
            return int(num_str[index:])

        max_product = 0
        for i in range(index, N - remaining_multiplications):
            current_number = int(num_str[index:i + 1])
            rest_max_product = find_max_product(i + 1, remaining_multiplications - 1)
            max_product = max(max_product, current_number * rest_max_product)

        return max_product

    return find_max_product(0, K)

