        max_prod = 0
        for i in range(1, len(nums) - (k - 1)):
            left = int(''.join(nums[:i]))
            right = split_and_multiply(nums[i:], k - 1)
            max_prod = max(max_prod, left * right)
        return max_prod

    return split_and_multiply(list(num_str), K)

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit() or N <= 0 or K < 0 or K >= N:
        raise ValueError("Invalid input: Ensure num_str is a digit string, N is positive, K is non-negative, and K is less than N.")

    # Initialize the dp array
    dp = [[-1] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1

    for i in range(1, N + 1):
        for j in range(min(i, K + 1)):
            for l in range(i):
                num = int(num_str[l:i])
                if j == 0 and l == 0:
                    dp[i][j] = max(dp[i][j], num)
                elif j > 0:
                    dp[i][j] = max(dp[i][j], dp[l][j - 1] * num)

    return dp[N][K]

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit() or N != len(num_str) or K < 0 or K >= N:
        raise ValueError("Invalid input: num_str must be a digit string of length N, and K must be between 0 and N-1.")

    def split_and_multiply(parts):
        product = 1
        for part in parts:
            product *= int(part)
        return product

    max_product = 0
    from itertools import combinations

    # Generate all possible positions to insert K multiplication signs
    for positions in combinations(range(1, N), K):
        parts = []
        start = 0
        for pos in positions:
            parts.append(num_str[start:pos])
            start = pos
        parts.append(num_str[start:])

        current_product = split_and_multiply(parts)
        if current_product > max_product:
            max_product = current_product

    return max_product

