def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    try:
        # Initialize counters for row and column separations
        row_separations = [0] * (M + 1)
        col_separations = [0] * (N + 1)

        # Count the number of chatting pairs that can be separated by each row or column
        for (Xi, Yi, Pi, Qi) in chatting_pairs:
            if Xi == Pi:
                # Chatting in the same row
                if Yi < Qi:
                    row_separations[Xi] += 1
                else:
                    row_separations[Xi] += 1
            elif Yi == Qi:
                # Chatting in the same column
                if Xi < Pi:
                    col_separations[Yi] += 1
                else:
                    col_separations[Yi] += 1

        # Find the top K rows and L columns with the most separations
        best_rows = sorted(range(1, M + 1), key=lambda x: row_separations[x], reverse=True)[:K]
        best_cols = sorted(range(1, N + 1), key=lambda x: col_separations[x], reverse=True)[:L]

        # Convert lists to space-separated strings
        best_rows_str = ' '.join(map(str, best_rows))
        best_cols_str = ' '.join(map(str, best_cols))

        return (best_rows_str, best_cols_str)

    except Exception as e:
        return ("", "")

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0:
        raise ValueError("Invalid dimensions or number of aisles/pairs.")
    if not all(1 <= Xi <= M and 1 <= Yi <= N and 1 <= Pi <= M and 1 <= Qi <= N for Xi, Yi, Pi, Qi in chatting_pairs):
        raise ValueError("Chatting pairs must be within the classroom dimensions.")

    horizontal_separations = [0] * (M + 1)
    vertical_separations = [0] * (N + 1)

    for Xi, Yi, Pi, Qi in chatting_pairs:
        if Xi == Pi:  # Same row, vertical aisle can separate them
            col1, col2 = min(Yi, Qi), max(Yi, Qi)
            for j in range(col1, col2):
                vertical_separations[j] += 1
        elif Yi == Qi:  # Same column, horizontal aisle can separate them
            row1, row2 = min(Xi, Pi), max(Xi, Pi)
            for i in range(row1, row2):
                horizontal_separations[i] += 1

    # Find the top K and L positions
    top_horizontal_positions = sorted(range(1, M), key=lambda x: horizontal_separations[x], reverse=True)[:K]
    top_vertical_positions = sorted(range(1, N), key=lambda x: vertical_separations[x], reverse=True)[:L]

    return ' '.join(map(str, top_horizontal_positions)), ' '.join(map(str, top_vertical_positions))

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0:
        raise ValueError("Invalid input dimensions or numbers of aisles/chatting pairs.")

    if K > M - 1 or L > N - 1:
        raise ValueError("Cannot add more aisles than possible slots in the grid.")

    hori_effect = [0] * (M + 1)
    vert_effect = [0] * (N + 1)

    for x1, y1, x2, y2 in chatting_pairs:
        if x1 == x2:
            # vertical separation needed
            if y1 < y2:
                vert_effect[y1] += 1
                vert_effect[y2] -= 1
            else:
                vert_effect[y2] += 1
                vert_effect[y1] -= 1
        elif y1 == y2:
            # horizontal separation needed
            if x1 < x2:
                hori_effect[x1] += 1
                hori_effect[x2] -= 1
            else:
                hori_effect[x2] += 1
                hori_effect[x1] -= 1

    for i in range(1, len(hori_effect)):
        hori_effect[i] += hori_effect[i - 1]

    for i in range(1, len(vert_effect)):
        vert_effect[i] += vert_effect[i - 1]

    hori_indices = sorted(range(1, M), key=lambda x: -hori_effect[x])[:K]
    vert_indices = sorted(range(1, N), key=lambda x: -vert_effect[x])[:L]

    return (' '.join(map(str, sorted(hori_indices))), ' '.join(map(str, sorted(vert_indices))))

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
