        if M <= 0 or N <= 0 or D < 0 or K < 0 or L < 0:
            raise ValueError("Invalid classroom dimensions or number of aisles/chatting pairs.")

        # Initialize counters for horizontal and vertical gaps
        horizontal_gaps = [0] * (M + 1)
        vertical_gaps = [0] * (N + 1)

        # Count how many chatting pairs can be separated by each row and column
        for pair in chatting_pairs:
            x1, y1, x2, y2 = pair
            if x1 == x2:  # Same row, vertical gap can separate
                min_col, max_col = min(y1, y2), max(y1, y2)
                for col in range(min_col, max_col):
                    vertical_gaps[col] += 1
            elif y1 == y2:  # Same column, horizontal gap can separate
                min_row, max_row = min(x1, x2), max(x1, x2)
                for row in range(min_row, max_row):
                    horizontal_gaps[row] += 1

        # Sort potential gap positions by the number of separations they can achieve
        horizontal_gaps = sorted(enumerate(horizontal_gaps), key=lambda x: x[1], reverse=True)
        vertical_gaps = sorted(enumerate(vertical_gaps), key=lambda x: x[1], reverse=True)

        # Select the top K horizontal and L vertical gaps
        selected_horizontal = [str(row) for row, _ in horizontal_gaps[:K]]
        selected_vertical = [str(col) for col, _ in vertical_gaps[:L]]

        return ' '.join(selected_horizontal), ' '.join(selected_vertical)

    except Exception as e:
        return str(e), str(e)

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be positive and number of passes must be non-negative.")
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] will store the number of ways to reach student i after j passes
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1  # Starting at student 0 with 0 passes

    for passes in range(1, m + 1):
        for student in range(n):
            left_student = (student - 1) % n
            right_student = (student + 1) % n
            dp[student][passes] = dp[left_student][passes - 1] + dp[right_student][passes - 1]

    return dp[0][m]

