def max_energy(beads):
    def merge_energy(a, b, c):
        return a * b * c

    n = len(beads)
    if n < 3:
        return 0

    # Extend the beads list to handle circular nature
    beads = beads + beads[:-1]
    n_extended = len(beads)

    # dp[i][j] will store the maximum energy we can get from merging beads[i] to beads[j]
    dp = [[0] * n_extended for _ in range(n_extended)]

    # Fill the table
    for length in range(3, n + 1):  # length of the subarray to consider
        for i in range(n):
            j = i + length - 1
            if j >= n_extended:
                continue
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + merge_energy(beads[i], beads[k], beads[j]))

    # The result is the maximum energy we can get for the original n beads
    return max(dp[i][i + n - 1] for i in range(n))

