def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a transformation map from rules
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[x].add(y)

    # BFS setup
    queue = deque([str(n)])
    visited = set([str(n)])

    while queue:
        current_str = queue.popleft()

        # Generate all possible transformations of the current number
        for i, digit in enumerate(current_str):
            if int(digit) in transform_map:
                for new_digit in transform_map[int(digit)]:
                    new_number_str = current_str[:i] + str(new_digit) + current_str[i+1:]
                    if new_number_str not in visited:
                        visited.add(new_number_str)
                        queue.append(new_number_str)

    return len(visited)

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a mapping of each digit to its possible transformations
    transformation_map = defaultdict(set)
    for x, y in rules:
        transformation_map[str(x)].add(str(y))
        transformation_map[str(x)].add(str(x))  # Include the original digit

    # Initialize BFS queue and set to track unique numbers
    queue = deque([str(n)])
    unique_numbers = set([str(n)])

    while queue:
        current_number = queue.popleft()
        length = len(current_number)

        # Generate all possible transformations of the current number
        for i in range(length):
            digit = current_number[i]
            if digit in transformation_map:
                for new_digit in transformation_map[digit]:
                    new_number = current_number[:i] + new_digit + current_number[i+1:]
                    if new_number not in unique_numbers:
                        unique_numbers.add(new_number)
                        queue.append(new_number)

    return len(unique_numbers)

