def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    try:
        if V < 0 or n < 0 or any(v < 0 for v in volumes):
            raise ValueError("All inputs must be non-negative.")

        # Initialize a list to store the maximum volume that can be achieved for each capacity up to V
        dp = [0] * (V + 1)

        # Iterate over each item
        for volume in volumes:
            # Update the dp array from right to left
            for w in range(V, volume - 1, -1):
                dp[w] = max(dp[w], dp[w - volume] + volume)

        # The maximum volume that can be packed in the box
        max_volume = dp[V]

        # The minimum remaining space in the box
        return V - max_volume

    except Exception as e:
        print(f"An error occurred: {e}")
        return V  # Return the full capacity as remaining space if an error occurs

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0 or n < 0 or any(v < 0 for v in volumes):
        raise ValueError("Capacity and volumes must be non-negative.")
    if n != len(volumes):
        raise ValueError("The number of items n must match the length of the volumes list.")

    # Initialize the DP array where dp[i] will be True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a subset with volume 0 is always possible (empty subset)

    for v in volumes:
        # Traverse backwards to avoid using the same item multiple times
        for j in range(V, v - 1, -1):
            if dp[j - v]:
                dp[j] = True

    # Find the maximum volume that can be achieved without exceeding V
    max_achievable_volume = next((i for i in range(V, -1, -1) if dp[i]), 0)

    return V - max_achievable_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # dp[i][j] will store the number of ways to use j pots with the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # There's one way to arrange 0 pots with 0 types of flowers

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

